// @whimtex-effect Samples/Unlit Smoke Density
// @control(_Opacity)
// @param hidden float _Opacity = 0.86 [0 .. 1]
// @param point _Center = (0.38, 0.32)
// @param float _Radius = 0.105 [0.02 .. 0.4]
// @param float _Detail = 0.32 [0 .. 1]
// @param float _Softness = 0.75 [0.1 .. 1]

float4 ApplyFX(float2 uv,float4 color){
    float n=saturate(color.r);
    float m=SampleInput(saturate(uv+float2(.08,.11))).r;
    float2 p=(uv-_Center)/_Radius;
    float2 q=p+float2(n-.5,m-.5)*_Detail*.65;
    float r=length(q);
    float density=exp(-pow(r/.78,lerp(4,2,_Softness))*1.2);
    float alpha=density*(1-smoothstep(.95,1.28,r))*_Opacity;
    alpha*=lerp(1,smoothstep(.05,.75,n),_Detail*.6);
    return float4(1,1,1,saturate(alpha));
}

